/**
 * NativeController - Renderer 進程直接調用 native MpvController
 *
 * 這個模組允許在 Renderer 進程中直接加載和使用 native video_player.node，
 * 消除 Main → Renderer 的 IPC 幀傳輸瓶頸。
 *
 * 前提條件：
 * - Electron 設定 nodeIntegration: true
 * - Electron 設定 contextIsolation: false
 *
 * 優勢：
 * - 消除 IPC 帶寬瓶頸（4K 60fps = 750MB/s → 0）
 * - 降低延遲（~100ms → ~16ms）
 * - 簡化架構
 */

/* eslint-disable @typescript-eslint/no-require-imports */

// ============================================================================
// 類型定義（與 video-service.ts 保持一致）
// ============================================================================

export interface VideoEvent {
    type: string;
    [key: string]: unknown;
}

export interface VideoState {
    position: number;
    duration: number;
    paused: boolean;
    volume: number;
    playing: boolean;
}

export interface FrameData {
    buffer: ArrayBuffer;
    width: number;
    height: number;
    rotation: number;
    format: 'rgba' | 'yuv420';
}

export interface FrameMetadata {
    width: number;
    height: number;
    rotation: number;
    format: 'rgba' | 'yuv420';
}

export interface TargetResolution {
    width: number;
    height: number;
}

export interface VideoMetadata {
    duration: number;
    width: number;
    height: number;
    rotation: number;
    format: string;
    videoCodec: string;
    audioCodec: string;
    bitrate: number;
    fps: number;
    isHdr: boolean;
    hdrPrimaries: string;
    hdrTransfer: string;
    hdrMaxLuminance: number;
    sampleRate: number;
    channels: number;
}

export interface HdrInfo {
    isHdr: boolean;
    primaries: string;
    transfer: string;
    maxLuminance: number;
    hdrModeEnabled: boolean;
}

export interface FileSupportResult {
    supported: boolean;
    hasVideo: boolean;
    hasAudio: boolean;
    error: string | null;
    format?: string;
    videoCodec?: string;
    audioCodec?: string;
}

interface NativeMetadata {
    videoCodec: string;
    audioCodec: string;
    format: string;
    bitrate: number;
    sampleRate: number;
    channels: number;
    // New fields from C++ GetMetadata()
    width: number;
    height: number;
    rotation: number;
    fps: number;
    isHdr: boolean;
    hdrPrimaries: string;
    hdrTransfer: string;
    hdrMaxLuminance: number;
}

// Native MpvController 接口
interface NativeMpvController {
    loadFile(filePath: string): boolean;
    seek(position: number, mode?: string): boolean;
    play(): boolean;
    pause(): boolean;
    stop(): boolean;
    getPosition(): number;
    getDuration(): number;
    getVolume(): number;
    isPaused(): boolean;
    isPlaying(): boolean;
    setVolume(volume: number): boolean;
    setSpeed(speed: number): boolean;
    setMute?(muted: boolean): boolean;
    getMute?(): boolean;
    setLoop?(loop: boolean): boolean;
    getLoop?(): boolean;
    setFastSeek?(enabled: boolean): boolean;
    renderFrame(targetWidth?: number, targetHeight?: number): ArrayBuffer | null;
    getFrameBuffer(): ArrayBuffer | null;
    getFrameAt?(time: number): ArrayBuffer | null;
    getScreenshotAt?(time: number): boolean;
    getVideoSize(): {
        width: number;
        height: number;
        rotation: number;
        renderWidth: number;
        renderHeight: number;
        fps: number;
        format: 'rgba' | 'yuv420';
    };
    getMetadata?(): NativeMetadata | null;
    getHdrInfo?(): HdrInfo | null;
    setHdrMode?(enabled: boolean): boolean;
    onEvent(callback: (event: VideoEvent) => void): void;
    destroy(): void;
    checkFileSupport(filePath: string): FileSupportResult;
}

interface NativeMpvControllerOptions {
    hwdec?: string;
    vo?: string;
    [key: string]: string | number | boolean | undefined;
}

interface VideoPlayerModule {
    MpvController: new (options?: NativeMpvControllerOptions) => NativeMpvController;
}

// ============================================================================
// Native Module 加載
// ============================================================================

let videoPlayerModule: VideoPlayerModule | null = null;
let moduleLoadError: Error | null = null;

/**
 * 獲取 native module 的可能路徑
 *
 * 優先級：
 * 1. 環境變量 MPV_NATIVE_MODULE_PATH（由主進程設置，最可靠）
 * 2. 打包後的標準路徑
 * 3. 開發模式的猜測路徑
 */
function getPossibleModulePaths(): string[] {
    const paths: string[] = [];

    // 檢查是否在 Node.js 環境
    if (typeof process === 'undefined' || typeof require === 'undefined') {
        console.warn('[NativeController] Not in Node.js environment');
        return paths;
    }

    // 1. 優先使用主進程設置的環境變量（最可靠）
    const envPath = process.env.MPV_NATIVE_MODULE_PATH;
    if (envPath) {
        console.log('[NativeController] Using path from MPV_NATIVE_MODULE_PATH:', envPath);
        paths.push(envPath);
        return paths;  // 直接返回，不需要猜測
    }

    // 2. Fallback: 自動猜測路徑
    const isElectron = !!(process.versions && process.versions.electron);
    if (!isElectron) {
        console.warn('[NativeController] Not in Electron environment');
        return paths;
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const path = require('path') as any;
    const cwd = process.cwd();

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const resourcesPath = (process as any).resourcesPath;
    const isPackaged = !!resourcesPath && !resourcesPath.includes('node_modules');

    console.log('[NativeController] Fallback path resolution:', { cwd, resourcesPath, isPackaged });

    const moduleName = 'video_player.node';
    const nativeSubPath = path.join('native', 'video-player', 'build', 'Release', moduleName);

    if (isPackaged && resourcesPath) {
        paths.push(
            path.join(resourcesPath, 'app.asar.unpacked', nativeSubPath),
            path.join(resourcesPath, 'native-addon', moduleName),
        );
    } else {
        paths.push(
            path.join(cwd, '..', 'mpv-player', nativeSubPath),
            path.join(cwd, 'packages', 'mpv-player', nativeSubPath),
            path.join(cwd, 'node_modules', '@eagle-app', 'mpv-video-player', nativeSubPath),
        );
    }

    return paths;
}

/**
 * 加載 native module
 */
function loadNativeModule(): VideoPlayerModule {
    if (videoPlayerModule) {
        return videoPlayerModule;
    }

    if (moduleLoadError) {
        throw moduleLoadError;
    }

    const possiblePaths = getPossibleModulePaths();
    console.log('[NativeController] Looking for native module...');

    for (const modulePath of possiblePaths) {
        try {
            console.log(`[NativeController]   Trying: ${modulePath}`);
            videoPlayerModule = require(modulePath) as VideoPlayerModule;
            console.log(`[NativeController]   SUCCESS: Loaded from ${modulePath}`);
            return videoPlayerModule;
        } catch (err) {
            console.log(`[NativeController]   FAILED: ${(err as Error).message}`);
            continue;
        }
    }

    moduleLoadError = new Error('Native module not found. Tried paths:\n' + possiblePaths.join('\n'));
    throw moduleLoadError;
}

/**
 * 檢查 native module 是否可用
 */
export function isNativeModuleAvailable(): boolean {
    try {
        loadNativeModule();
        return true;
    } catch {
        return false;
    }
}

// ============================================================================
// NativeController 類
// ============================================================================

/**
 * NativeController - Renderer 進程中的 MpvController 包裝
 *
 * 提供與 IPC 模式相同的 API，但直接在 Renderer 進程中執行
 */
export class NativeController {
    private controller: NativeMpvController | null = null;
    private eventCallbacks: Set<(event: VideoEvent) => void> = new Set();
    private currentVideoPath: string | null = null;
    private _muted = false;
    private _previousVolume = 100;
    private _loop = false;
    private _destroyed = false;

    /**
     * 創建 NativeController 實例
     * @param options.hwdec - 硬體解碼模式
     * @param options.thumbnailMode - 縮圖模式（自動套用縮放 + fps 限制）
     * @param options.thumbnailWidth - 縮圖寬度（預設 320）
     */
    constructor(options?: {
        hwdec?: 'auto' | 'no';
        thumbnailMode?: boolean;
        thumbnailWidth?: number;
    }) {
        try {
            const module = loadNativeModule();
            this.controller = new module.MpvController({
                hwdec: options?.hwdec ?? 'auto',
                thumbnailMode: options?.thumbnailMode ?? false,
                thumbnailWidth: options?.thumbnailWidth ?? 320,
            });

            // 設置事件回調
            this.controller.onEvent((event: VideoEvent) => {
                this.handleEvent(event);
            });

            console.log('[NativeController] Instance created');
        } catch (error) {
            console.error('[NativeController] Failed to create instance:', error);
            throw error;
        }
    }

    /**
     * 處理來自 native 的事件
     */
    private handleEvent(event: VideoEvent): void {
        // 分發給所有監聽器
        for (const callback of this.eventCallbacks) {
            try {
                callback(event);
            } catch (error) {
                console.error('[NativeController] Event callback error:', error);
            }
        }
    }

    /**
     * 訂閱事件
     */
    onEvent(callback: (event: VideoEvent) => void): () => void {
        this.eventCallbacks.add(callback);
        return () => {
            this.eventCallbacks.delete(callback);
        };
    }

    // ========================================================================
    // 播放控制
    // ========================================================================

    loadFile(filePath: string): boolean {
        if (!this.controller || this._destroyed) return false;
        const success = this.controller.loadFile(filePath);
        if (success) {
            this.currentVideoPath = filePath;
        }
        return success;
    }

    play(): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.play();
    }

    pause(): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.pause();
    }

    stop(): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.stop();
    }

    seek(position: number, mode: string = 'absolute'): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.seek(position, mode);
    }

    togglePlay(): boolean {
        if (!this.controller || this._destroyed) return false;
        if (this.controller.isPaused()) {
            return this.controller.play();
        } else {
            return this.controller.pause();
        }
    }

    // ========================================================================
    // 狀態查詢
    // ========================================================================

    getPosition(): number {
        if (!this.controller || this._destroyed) return 0;
        return this.controller.getPosition();
    }

    getDuration(): number {
        if (!this.controller || this._destroyed) return 0;
        return this.controller.getDuration();
    }

    isPaused(): boolean {
        if (!this.controller || this._destroyed) return true;
        return this.controller.isPaused();
    }

    isPlaying(): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.isPlaying();
    }

    getState(): VideoState {
        if (!this.controller || this._destroyed) {
            return { position: 0, duration: 0, paused: true, volume: 0, playing: false };
        }
        return {
            position: this.controller.getPosition(),
            duration: this.controller.getDuration(),
            paused: this.controller.isPaused(),
            volume: this.controller.getVolume(),
            playing: this.controller.isPlaying(),
        };
    }

    getVideoSize(): {
        width: number;
        height: number;
        rotation: number;
        renderWidth: number;
        renderHeight: number;
        fps: number;
        format: 'rgba' | 'yuv420';
    } {
        if (!this.controller || this._destroyed) {
            return { width: 0, height: 0, rotation: 0, renderWidth: 0, renderHeight: 0, fps: 0, format: 'yuv420' };
        }
        return this.controller.getVideoSize();
    }

    // ========================================================================
    // 屬性設置
    // ========================================================================

    setVolume(volume: number): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.setVolume(volume);
    }

    setSpeed(speed: number): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.setSpeed(speed);
    }

    setMute(muted: boolean): boolean {
        if (!this.controller || this._destroyed) return false;

        if (muted && !this._muted) {
            this._previousVolume = this.controller.getVolume();
            this._muted = true;
            return this.controller.setVolume(0);
        } else if (!muted && this._muted) {
            this._muted = false;
            return this.controller.setVolume(this._previousVolume);
        }
        return true;
    }

    getMute(): boolean {
        return this._muted;
    }

    setLoop(loop: boolean): boolean {
        this._loop = loop;
        return true;
    }

    getLoop(): boolean {
        return this._loop;
    }

    setFastSeek(enabled: boolean): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.setFastSeek?.(enabled) ?? true;
    }

    // ========================================================================
    // 幀渲染（核心功能）
    // ========================================================================

    /**
     * 渲染一幀並返回數據
     *
     * @param targetWidth 目標寬度（用於 GPU 縮放）
     * @param targetHeight 目標高度（用於 GPU 縮放）
     * @returns 幀數據或 null
     */
    renderFrame(targetWidth?: number, targetHeight?: number): FrameData | null {
        if (!this.controller || this._destroyed) return null;

        const buffer = this.controller.renderFrame(targetWidth, targetHeight);
        if (!buffer) return null;

        const size = this.controller.getVideoSize();
        return {
            buffer,
            width: size.renderWidth || size.width,
            height: size.renderHeight || size.height,
            rotation: size.rotation,
            format: size.format,
        };
    }

    /**
     * 獲取幀元數據（不渲染新幀）
     */
    getFrameMetadata(): FrameMetadata | null {
        if (!this.controller || this._destroyed) return null;

        const size = this.controller.getVideoSize();
        if (size.width <= 0 || size.height <= 0) return null;

        return {
            width: size.renderWidth || size.width,
            height: size.renderHeight || size.height,
            rotation: size.rotation,
            format: size.format,
        };
    }

    // ========================================================================
    // 元數據和 HDR
    // ========================================================================

    getMetadata(): VideoMetadata | null {
        if (!this.controller || this._destroyed) return null;

        const size = this.controller.getVideoSize();
        const nativeMeta = this.controller.getMetadata?.();

        // Prefer nativeMeta values when available (more reliable from C++ cached atomics)
        return {
            duration: this.controller.getDuration(),
            width: nativeMeta?.width ?? size.width,
            height: nativeMeta?.height ?? size.height,
            rotation: nativeMeta?.rotation ?? size.rotation,
            fps: nativeMeta?.fps ?? size.fps,
            format: nativeMeta?.format ?? '',
            videoCodec: nativeMeta?.videoCodec ?? '',
            audioCodec: nativeMeta?.audioCodec ?? '',
            bitrate: nativeMeta?.bitrate ?? 0,
            sampleRate: nativeMeta?.sampleRate ?? 0,
            channels: nativeMeta?.channels ?? 0,
            isHdr: nativeMeta?.isHdr ?? false,
            hdrPrimaries: nativeMeta?.hdrPrimaries ?? '',
            hdrTransfer: nativeMeta?.hdrTransfer ?? '',
            hdrMaxLuminance: nativeMeta?.hdrMaxLuminance ?? 0,
        };
    }

    getHdrInfo(): HdrInfo | null {
        if (!this.controller || this._destroyed) return null;
        return this.controller.getHdrInfo?.() ?? null;
    }

    setHdrMode(enabled: boolean): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.setHdrMode?.(enabled) ?? false;
    }

    // ========================================================================
    // 其他功能
    // ========================================================================

    checkFileSupport(filePath: string): FileSupportResult {
        if (!this.controller || this._destroyed) {
            return { supported: false, hasVideo: false, hasAudio: false, error: 'Controller destroyed' };
        }
        return this.controller.checkFileSupport(filePath);
    }

    requestScreenshot(time: number): boolean {
        if (!this.controller || this._destroyed) return false;
        return this.controller.getScreenshotAt?.(time) ?? false;
    }

    getCurrentVideoPath(): string | null {
        return this.currentVideoPath;
    }

    isDestroyed(): boolean {
        return this._destroyed;
    }

    // ========================================================================
    // 清理
    // ========================================================================

    destroy(): void {
        if (this._destroyed) return;

        this._destroyed = true;
        this.eventCallbacks.clear();

        if (this.controller) {
            try {
                this.controller.destroy();
            } catch (error) {
                console.error('[NativeController] Error during destroy:', error);
            }
            this.controller = null;
        }

        console.log('[NativeController] Instance destroyed');
    }
}
